    # The pattern tiles have a 5-cell pitch, with 4x4 motif areas.
    for r0 in range(0, h, 5):
        for c0 in range(0, w, 5):
            r1, c1 = min(h, r0 + 4), min(w, c0 + 4)
            cells = [(r, c) for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] == 2]
            if not cells:
                continue
            # Choose the exposed tip: a 2-cell with the fewest orthogonal
            # 2-neighbors, preferring the outer edge of the motif.
            def rank(p):
                r, c = p
                n = sum(0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 2
                        for rr, cc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)))
                edge = min(r-r0, r1-1-r, c-c0, c1-1-c)
                return (n, edge, r, c)
            r, c = min(cells, key=rank)
            out[r][c] = 8

    return out
